function auditOperations(){
 const h=eval("("+load("runtime_fixture_sha256_function_source")+")");
 const u=eval("("+load("four_partition_utf8_source")+")");
 const s1=eval("("+load("four_partition_sha1_source")+")");
 const merkle=eval("("+load("four_partition_merkle_source")+")");
 const f=load("rsp130_operations_first_files"), oldf=load("rsp130_finite_first_files");
 const parsed=n=>JSON.parse(f[n].text), need=(x,m)=>{if(!x)throw Error(m)};
 const canon=x=>JSON.stringify(x&&typeof x==="object"?(Array.isArray(x)?x.map(v=>JSON.parse(canon(v))):Object.fromEntries(Object.keys(x).sort().map(k=>[k,JSON.parse(canon(x[k]))]))):x);
 const eq=(a,b,m)=>need(canon(a)===canon(b),m);
 const config=load("rsp130_operations_manifest"), old=load("rsp130_finite_first_terminal");
 const outcome=parsed("job-outcome.json"), results=parsed("operations-results.json");
 need(outcome.passed===true&&outcome.error===null&&outcome.source_unchanged===true,"outcome");
 need(outcome.source_sha===config.source_sha&&outcome.source_tree===config.source_tree,"source outcome");
 need(outcome.harness_sha==="12549dcc39d1b3e8ce97e97e1dff825d51635cf7"&&outcome.run_id==="35462548025"&&outcome.run_attempt==="1","run binding");
 eq(results.errors,[],"operation errors");
 need(results.fresh_functional_test_bodies===0&&results.historical_functional_cases===45&&results.historical_functional_overall_run==="failure","no replay");
 need(results.timing_measurement===false&&results.optimization_selected===false,"scope");
 need(f["source-before.json"].text===f["source-after.json"].text,"whole source after");
 need(f["environment-before.json"].text===f["environment-after.json"].text,"whole environment after");
 const source=parsed("source-before.json"),env=parsed("environment-before.json");
 eq(env.installed_versions,config.installed_versions,"all69 versions");need(env.installed_count===69,"69 count");
 need(Object.keys(env.dependency_files).length===12817,"dependency file count");
 const sourceLeaves=Object.entries(source.files).map(([path,r])=>({path,sha:r.git_blob,mode:r.mode}));
 const baseLeaves=Object.entries(source.baseline_files).map(([path,r])=>({path,sha:r.git_blob,mode:r.mode}));
 need(sourceLeaves.length===4623&&baseLeaves.length===4622,"leaf counts");
 need(merkle(sourceLeaves,s1,u)===config.source_tree,"source Merkle");
 need(merkle(baseLeaves,s1,u)===config.baseline.tree,"baseline Merkle");
 for(const r of load("rsp130_operations_files"))eq(source.harness_files[r.path],{bytes:r.bytes,sha256:r.sha256},"actual harness "+r.path);
 need(Object.keys(source.harness_files).length===20,"harness count");
 for(const [path,pin]of Object.entries(config.candidate_files)){
  eq(source.files[path],pin,"candidate pin "+path);
  const v=f["source-payload/current/"+path];need(v&&v.bytes===pin.bytes&&v.sha256===pin.sha256,"retained source "+path);
  need(s1(u("blob "+v.bytes+"\0").concat(u(v.text)))===pin.git_blob,"retained Git "+path);
 }
 for(const[path,pin]of Object.entries(config.baseline_input_files))eq(source.baseline_files[path],pin,"baseline input "+path);
 const im=parsed("artifact-manifest.json");
 for(const[name,pin]of Object.entries(im))eq({bytes:f[name].bytes,sha256:f[name].sha256},pin,"all member "+name);
 need(Object.keys(f).length===49&&Object.keys(im).length===47,"member counts");
 need(f["retained-original-terminal.json"].text===old.text,"whole original failed terminal");
 const rawNames=["baseline-existing-collection.json","candidate-existing-collection.json","candidate-new-collection.json","existing-execution.json","new-execution.json","existing-execution-junit.xml","new-execution-junit.xml"];
 for(const name of rawNames)need(f["original-functional/"+name].text===oldf[name].text,"whole original functional "+name);
 const prior=parsed("prior-functional-admission.json");
 need(prior.original_failure_preserved&&prior.bodies_reexecuted===0&&prior.historical_passes===45&&prior.historical_phases===135,"prior functional scope");
 eq(prior.original_functional_results,old.parsed.finite_results.results,"same original45 results");
 eq(results.results.prior_functional,prior,"embedded prior");
 const deps=parsed("prior-fixture-currentness.json");
 need(deps.historical_bodies_reexecuted===false&&deps.historical_fixture_source_bytes_match_current_source_or_fresh_dependencies===true,"fixtures scope");
 eq(deps.fresh_owned_environment_versions,env.installed_versions,"fixture environment");
 for(const row of deps.historical_definition_records){
  let actual;
  if(row.path.startsWith("@tests/"))actual=source.files[row.path.slice(7)];
  else if(row.path.startsWith("@environment/"))actual=env.dependency_files[row.path.slice(13)];
  else throw Error("unbounded fixture path");
  need(actual&&actual.sha256===row.sha256,"fixture byte "+row.path);
 }
 eq(results.results.prior_fixture_currentness,deps,"embedded fixtures");
 const steps=parsed("commands.json");eq(steps,outcome.steps,"outcome commands");eq(steps,parsed("steps.json"),"steps commands");
 const expectedNames=["source-admission-before-environment","uv-version","create-validation-environment","frozen-project-install","dependency-compatibility","environment-before","calibration-unprimed-negative","calibration-first-load","calibration-nested-comparison","calibration-exception-cleanup","six-separate-operation-cells","environment-after"];
 eq(steps.map(x=>x.name),expectedNames,"exact12 commands");
 const pidKeys=[];
 for(const row of steps){
  need(row.passed===true&&row.returncode===0&&row.timed_out===false&&!row.error,"command success "+row.name);
  need(f[row.name+".log"].sha256===row.log_sha256&&f[row.name+".log"].bytes===row.log_bytes,"command log "+row.name);
  const g=row.group_cleanup,z=g.snapshots.at(-1),id=row.leader_identity;
  need(g.passed===true&&g.no_live_members_in_original_group===true&&g.errors.length===0&&z.live.length===0&&z.inspection_errors.length===0,"retirement "+row.name);
  need(row.pid===id.pid&&id.pid===id.pgrp&&id.pgrp===id.session&&id.uid===1001,"owned leader");
  pidKeys.push(id.pid+":"+id.start_ticks);
  need(!row.command.includes("pytest"),"no pytest replay command");
 }
 need(new Set(pidKeys).size===12,"distinct actual children");
 need(outcome.all_original_owned_groups_retired===true&&outcome.no_complete_descendant_cleanup_certificate===true,"retirement scope");
 const calibrationNames=["unprimed-negative","first-load","nested-comparison","exception-cleanup"];
 const calibrations=calibrationNames.map(name=>parsed("calibration-"+name+".json"));
 eq(results.results.calibrations,calibrations,"all actual calibrations embedded");
 for(const row of calibrations){
  need(row.passed&&row.sources_unchanged&&row.product_callbacks_executed===0&&row.discarded_product_warmup_calls===0,"calibration scope");
  need(row.trace_after_is_none&&row.profile_after_is_none&&row.interpreter_opcode_latch_reset_claimed===false,"trace cleanup");
  eq(row.before,row.after,"calibration source");
  need(row.python.version.startsWith("3.12.13 ")&&row.python.executable.sha256===env.launchers.python.sha256,"owned Python");
  const pin=row.case==="unprimed-negative"?config.original_probe:config.corrected_probe;
  need(row.before[0].sha256===pin.sha256&&row.before[0].bytes===pin.bytes,"actual probe source");
  need(row.before[1].sha256===config.calibration.sha256&&row.before[1].bytes===config.calibration.bytes,"actual calibration source");
 }
 eq(calibrations[0].counts,{explicit_equal_comparisons:0,snapshot_id_load_attr:0},"unprimed negative zero");
 need(calibrations[0].negative_control_observed===true,"negative observed");
 eq(calibrations[1].counts,{explicit_equal_comparisons:0,snapshot_id_load_attr:1},"corrected first load");
 for(const row of calibrations.slice(0,2)){
  eq(row.unrelated_calls,[["calibration-key","calibration-key"]],"actual unrelated callback");
  need(row.unrelated_code_is_not_a_nested_callback_constant===true,"separate callback code");
  need(row.unrelated_instruction_map[0].instructions.filter(x=>x.opname==="LOAD_ATTR"&&x.argval==="snapshot_id").length===2,"unrelated two reads");
  need(row.synthetic_instruction_map[0].instructions.filter(x=>x.opname==="LOAD_ATTR"&&x.argval==="snapshot_id").length===1,"owned one read");
 }
 eq(calibrations[2].counts,{explicit_equal_comparisons:1,snapshot_id_load_attr:2},"nested count");
 need(calibrations[2].synthetic_instruction_map.length===2,"nested separate code");
 eq(calibrations[3].exception,{activation_frame_opcode_flags_after:[false],args:["calibration-key"],counted_frames:1,type:"OwnedFailure"},"exception and prior flag");
