 need(cells.passed&&cells.sources_unchanged&&cells.operation_count_only&&cells.runtime_or_performance_qualification===false,"operation scope");
 eq(cells.before,cells.after,"operation source unchanged");
 need(cells.cells.length===6,"six actual cells");
 for(let i=0;i<6;i++){
  const row=cells.cells[i],[S,P]=config.operation_cells[i];eq([row.snapshots,row.sources],[S,P],"exact pair");
  eq(row.original,{snapshot_id_load_attr:2*S*P+S,explicit_equal_comparisons:S*P},"actual original formula");
  eq(row.candidate,{snapshot_id_load_attr:S+P,explicit_equal_comparisons:0},"actual candidate formula");
  need(row.expected_original_key_loads===2*S*P+S&&row.expected_candidate_key_loads===S+P&&row.exact_key_and_source_object_order_equal,"actual parity");
 }
