 for(const bridge of proof.format_bridges){
  need(bridge.passed&&bridge.full_ast_equal_including_type_comments_and_type_ignore_line_fields&&bridge.canonical_tokens_equal&&bridge.comments_and_statement_token_anchors_equal,"strict bridge flags");
