 }
 return {schema:"pr2974-rsp130-opcode-independent-original-data-audit.v1",source_sha:config.source_sha,source_tree:config.source_tree,harness_sha:outcome.harness_sha,
 actual_commands:12,successful_commands:12,calibrations:calibrations.map(row=>({case:row.case,counts:row.counts??null,exception:row.exception??null,trace_restored:row.trace_after_is_none,unrelated_calls:row.unrelated_calls,probe_sha256:row.before[0].sha256})),
