 actual_fresh_functional_test_bodies:0,historical_functional_cases:45,historical_phases:135,original_overall_failure_preserved:true,
 all_seven_historical_raw_files_exact:true,source_files:sourceLeaves.length,baseline_files:baseLeaves.length,harness_files:20,whole_source_and_environment_unchanged:true,
 installed_distributions:69,dependency_files:Object.keys(env.dependency_files).length,historical_definition_records:deps.historical_definition_records.length,
